def camel_to_snake(s: str) -> str:
    """Convert camelCase or PascalCase to snake_case.
    Consecutive capitals stay together (HTTPServer -> http_server)."""
    if not s:
        return ''
    res = []
    prev_lower = False
    for i, ch in enumerate(s):
        if ch.isupper():
            if i != 0 and (prev_lower or (i+1 < len(s) and s[i+1].islower())):
                res.append('_')
            res.append(ch.lower())
            prev_lower = False
        else:
            res.append(ch)
            prev_lower = True
    return ''.join(res)

def parse_price(s: str) -> float:
    """Parse a US-formatted price string like '$1,200.50' into a float."""
    if not s:
        raise ValueError("Empty string")
    # Remove leading dollar sign and commas
    cleaned = s.lstrip('$').replace(',', '')
    # If no decimal point, interpret as integer dollars
    if '.' not in cleaned:
        return float(int(cleaned))
    return float(cleaned)

def flatten(xs: list) -> list:
    """Flatten an arbitrarily nested list of ints, preserving left-to-right order."""
    result = []
    for item in xs:
        if isinstance(item, list):
            result.extend(flatten(item))
        else:
            result.append(item)
    return result

def run_length_encode(s: str) -> str:
    """Compress runs of repeated characters as <char><count>. Single characters keep count 1."""
    if not s:
        return ""
    result = []
    current_char = s[0]
    count = 1
    for ch in s[1:]:
        if ch == current_char:
            count += 1
        else:
            result.append(f"{current_char}{count}")
            current_char = ch
            count = 1
    result.append(f"{current_char}{count}")
    return "".join(result)

def fizzbuzz(n: int) -> list:
    """Return the FizzBuzz strings for 1..n ('Fizz' for multiples of 3, 'Buzz' for 5, 'FizzBuzz' for both)."""
    result = []
    for i in range(1, n + 1):
        f = i % 3 == 0
        b = i % 5 == 0
        if f and b:
            result.append('FizzBuzz')
        elif f:
            result.append('Fizz')
        elif b:
            result.append('Buzz')
        else:
            result.append(str(i))
    return result

def shipping_cost(kg: float) -> float:
    """Flat $5.00 up to 1 kg, then $2.00 per additional started kg."""
    if kg <= 1:
        return 5.0
    # additional weight beyond 1 kg
    extra = kg - 1
    # ceil to next whole kg
    import math
    return 5.0 + 2.0 * math.ceil(extra)

